"use client";
import { scrollAreaListChildren } from "@/components/ui/scroll-area";

import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-menubar";
import {
  useFlowAppearance,
  useFlowGroup,
} from "@/lib/sahajiv-motion/use-flow";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { assignMotionRef } from "@/lib/sahajiv-motion/refs";

function useRetainedMenuContentRef(ref?: React.Ref<HTMLDivElement>) {
  const nodeRef = React.useRef<HTMLDivElement | null>(null);
  const composedRef = React.useCallback((node: HTMLDivElement | null) => {
    nodeRef.current = node;
    const release = assignMotionRef(ref, node);
    return () => {
      nodeRef.current = null;
      release();
    };
  }, [ref]);
  return { nodeRef, composedRef };
}

import { adornItem, itemText, type ItemAdornmentItemProps } from "@/components/ui/item-adornment";
import { StateChevron, AnimatedIcon } from "@/components/ui/animated-icon";

export type MenubarProps = React.ComponentProps<typeof Primitive.Root>;
export function Menubar({ className, ref, ...props }: MenubarProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.Root
      ref={morphRef}
      data-slot="menubar"
      data-part="root"
      className={cn(
        "v-menubar inline-flex gap-[var(--s-1)] p-1 bg-[var(--card)] rounded-[var(--r-pill)]",
        className,
      )}
      {...props}
    />
  );
}
export type MenubarMenuProps = React.ComponentProps<typeof Primitive.Menu>;
export function MenubarMenu(props: MenubarMenuProps) {
  return <Primitive.Menu {...props} />;
}
export type MenubarPortalProps = React.ComponentProps<typeof Primitive.Portal>;
export function MenubarPortal(props: MenubarPortalProps) {
  return <Primitive.Portal {...props} />;
}
export type MenubarGroupProps = React.ComponentProps<typeof Primitive.Group>;
export function MenubarGroup(props: MenubarGroupProps) {
  return <Primitive.Group data-slot="menubar-group" {...props} />;
}
export type MenubarRadioGroupProps = React.ComponentProps<
  typeof Primitive.RadioGroup
>;
export function MenubarRadioGroup(props: MenubarRadioGroupProps) {
  return <Primitive.RadioGroup data-slot="menubar-radiogroup" {...props} />;
}
export type MenubarSubProps = React.ComponentProps<typeof Primitive.Sub>;
export function MenubarSub(props: MenubarSubProps) {
  return <Primitive.Sub {...props} />;
}
export type MenubarTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
> & { chevron?: boolean };
export function MenubarTrigger({
  className,
  children,
  chevron = true,
  ref,
  ...props
}: MenubarTriggerProps) {
  const morphRef = useMorph<HTMLButtonElement>("buttons", ref);
  return (
    <Primitive.Trigger
      ref={morphRef}
      data-slot="menubar-trigger"
      data-part="trigger"
      data-menu=""
      className={cn(
        "v-menubar__trigger h-8 px-[var(--s-4)] rounded-[var(--r-pill)] text-[length:var(--fs-control)] font-medium",
        className,
      )}
      {...props}
    >{adornItem(children, false, "", props.asChild, chevron ? <StateChevron /> : null)}</Primitive.Trigger>
  );
}
export const menubarContentVariants = cva(
  "v-menu [background:var(--popover)] [border-radius:var(--r-card-sm)] [padding:var(--s-2)] [min-width:200px] [box-shadow:var(--shadow-float)] [border:1px_solid_var(--v-border)] [display:grid] [gap:2px]",
);
export type MenubarContentProps = React.ComponentProps<
  typeof Primitive.Content
>;
export function MenubarContent({
  className,
  ref,
  children,
  sideOffset = 6,
  onInteractOutside,
  ...props
}: MenubarContentProps) {
  const { nodeRef, composedRef } = useRetainedMenuContentRef(ref);
  const morphRef = useMorph<HTMLDivElement>("surfaces", composedRef);
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[data-highlighted]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(true, groupRef, "grow");
  return (
    <Primitive.Portal>
      <Primitive.Content
        ref={flowRef}
        data-slot="menubar-content"
        data-part="content"
        sideOffset={sideOffset}
        className={cn(menubarContentVariants(), className)}
        {...props}
        onInteractOutside={(event) => {
          onInteractOutside?.(event);
          // A retained closing menu must not dismiss the next menu when its
          // keyboard focus enters that sibling before the old exit finishes.
          if (nodeRef.current?.dataset.state === "closed") event.preventDefault();
        }}
      >
        {scrollAreaListChildren(children, props.asChild)}
      </Primitive.Content>
    </Primitive.Portal>
  );
}
export type MenubarSubContentProps = React.ComponentProps<
  typeof Primitive.SubContent
>;
export function MenubarSubContent({
  className,
  children,
  ref,
  onInteractOutside,
  ...props
}: MenubarSubContentProps) {
  const { nodeRef, composedRef } = useRetainedMenuContentRef(ref);
  const morphRef = useMorph<HTMLDivElement>("surfaces", composedRef);
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[data-highlighted]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(true, groupRef, "grow");
  return (
    <Primitive.Portal>
      <Primitive.SubContent
        ref={flowRef}
        data-slot="menubar-sub-content"
        data-part="content"
        className={cn(menubarContentVariants(), className)}
        {...props}
        onInteractOutside={(event) => {
          onInteractOutside?.(event);
          if (nodeRef.current?.dataset.state === "closed") event.preventDefault();
        }}
      >{scrollAreaListChildren(children, props.asChild)}</Primitive.SubContent>
    </Primitive.Portal>
  );
}
export type MenubarItemProps = React.ComponentProps<typeof Primitive.Item> & {
  variant?: "default" | "danger";
  inset?: boolean;
} & ItemAdornmentItemProps;
export function MenubarItem({
  className,
  children,
  adornment,
  adornmentId,
  variant,
  inset,
  ref,
  ...props
}: MenubarItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.Item
      ref={morphRef}
      data-slot="menubar-item"
      data-part="item"
      data-inset={inset || undefined}
      className={cn(
        "v-menu__item flex items-center gap-[var(--s-3)] min-h-10 px-[var(--s-3)] rounded-[var(--r-md)] text-[length:var(--fs-control)] w-full text-left whitespace-nowrap outline-none",
        variant === "danger" && "-danger",
        className,
  children,
  adornment,
  adornmentId,
      )}
      {...props}
    >{adornItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild)}</Primitive.Item>
  );
}
export type MenubarSubTriggerProps = React.ComponentProps<
  typeof Primitive.SubTrigger
> & { inset?: boolean } & ItemAdornmentItemProps;
export function MenubarSubTrigger({
  className,
  adornment,
  adornmentId,
  inset,
  children,
  ref,
  ...props
}: MenubarSubTriggerProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.SubTrigger
      ref={morphRef}
      data-slot="menubar-sub-trigger"
      data-part="item"
      data-inset={inset || undefined}
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <StateChevron direction="right" />)}
    </Primitive.SubTrigger>
  );
}
export type MenubarCheckboxItemProps = React.ComponentProps<
  typeof Primitive.CheckboxItem
> & ItemAdornmentItemProps;
export function MenubarCheckboxItem({
  className,
  adornment,
  adornmentId,
  children,
  ref,
  ...props
}: MenubarCheckboxItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.CheckboxItem
      ref={morphRef}
      data-slot="menubar-checkbox-item"
      data-part="item"
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <span className="v-menu__check" aria-hidden="true"><Primitive.ItemIndicator data-slot="menubar-item-indicator" data-part="indicator"><AnimatedIcon name="check" preset="validation" /></Primitive.ItemIndicator></span>)}
    </Primitive.CheckboxItem>
  );
}
export type MenubarRadioItemProps = React.ComponentProps<
  typeof Primitive.RadioItem
> & ItemAdornmentItemProps;
export function MenubarRadioItem({
  className,
  adornment,
  adornmentId,
  children,
  ref,
  ...props
}: MenubarRadioItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.RadioItem
      ref={morphRef}
      data-slot="menubar-radio-item"
      data-part="item"
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <span className="v-menu__check" aria-hidden="true"><Primitive.ItemIndicator data-slot="menubar-item-indicator" data-part="indicator"><AnimatedIcon name="dot" preset="validation" /></Primitive.ItemIndicator></span>)}
    </Primitive.RadioItem>
  );
}
export type MenubarLabelProps = React.ComponentProps<typeof Primitive.Label>;
export function MenubarLabel({ className, ...props }: MenubarLabelProps) {
  return (
    <Primitive.Label
      data-slot="menubar-label"
      data-part="group"
      className={cn("v-menu__group", className)}
      {...props}
    />
  );
}
export type MenubarSeparatorProps = React.ComponentProps<
  typeof Primitive.Separator
>;
export function MenubarSeparator({
  className,
  ...props
}: MenubarSeparatorProps) {
  return (
    <Primitive.Separator
      data-slot="menubar-separator"
      data-part="separator"
      className={cn("v-menu__sep", className)}
      {...props}
    />
  );
}
export type MenubarShortcutProps = React.ComponentProps<"span">;
export function MenubarShortcut({ className, ...props }: MenubarShortcutProps) {
  return (
    <span
      data-slot="menubar-shortcut"
      className={cn(
        "ml-auto text-[11px] text-[color:var(--muted-foreground)]",
        className,
      )}
      {...props}
    />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-menu__item:where([data-slot="menubar"], [data-slot^="menubar-"]) {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  min-height: 40px;
  padding: 0 var(--s-3);
  border-radius: var(--r-md);
  font-size: var(--fs-control);
  width: 100%;
  text-align: left;
  white-space: nowrap;
}
.v-menu__item:where([data-slot="menubar"], [data-slot^="menubar-"]):hover,
.v-menu__item:where(
    [data-slot="menubar"],
    [data-slot^="menubar-"]
  )[data-highlighted] {
  background: var(--v-beige);
}
.v-menu__item:where([data-slot="menubar"], [data-slot^="menubar-"]).-danger {
  color: var(--v-danger-ink);
}
.v-menu__sep:where([data-slot="menubar"], [data-slot^="menubar-"]) {
  height: 1px;
  background: var(--v-border);
  margin: 4px 0;
}
.v-menu__group:where([data-slot="menubar"], [data-slot^="menubar-"]) {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted-foreground);
  padding: 8px 12px 4px;
}
.v-menubar:where([data-slot="menubar"], [data-slot^="menubar-"]) {
  display: inline-flex;
  gap: var(--s-1);
  padding: 4px;
  background: var(--card);
  border-radius: var(--r-pill);
}
.v-menubar__trigger:where([data-slot="menubar"], [data-slot^="menubar-"]) {
  height: 32px;
  padding: 0 var(--s-4);
  border-radius: var(--r-pill);
  font-size: var(--fs-control);
  font-weight: 500;
}
.v-menubar__trigger:where(
    [data-slot="menubar"],
    [data-slot^="menubar-"]
  )[aria-expanded="true"],
.v-menubar__trigger:where(
    [data-slot="menubar"],
    [data-slot^="menubar-"]
  ):hover {
  background: var(--v-ink);
  color: var(--v-on-ink);
}
.v-menu:where([data-slot="menubar"], [data-slot^="menubar-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where(
    [data-slot="menubar"],
    [data-slot^="menubar-"]
  )::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.v-menu:where(
    [data-slot="menubar"],
    [data-slot^="menubar-"]
  )::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 999px;
}
.v-menu:where(
    [data-slot="menubar"],
    [data-slot^="menubar-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-ink) 34%, transparent);
  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-menu:where([data-slot="menubar"], [data-slot^="menubar-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where([data-slot="menubar"], [data-slot^="menubar-"]) {
  scrollbar-gutter: stable;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="menubar"],
  [data-slot^="menubar-"],
  [data-slot="menubar"]::before,
  [data-slot="menubar"]::after,
  [data-slot^="menubar-"]::before,
  [data-slot^="menubar-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot^="menubar-"][data-inset] {
  padding-left: 32px;
}
[data-slot^="menubar-"][data-disabled] {
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
[data-slot^="menubar-"][data-part="item"][data-highlighted] {
  outline: none;
  background: var(--v-beige);
}

[data-slot="menubar-content"], [data-slot="menubar-sub-content"] {
 min-width:min(200px,calc(100vw - 24px)); max-width:calc(100vw - 24px);
 max-height:min(480px,var(--radix-menubar-content-available-height,calc(100dvh - 32px)));
 overflow:visible; overscroll-behavior:contain; overflow-wrap:anywhere;
}
[data-slot="menubar-item"] { min-width:0; height:auto; min-height:36px; white-space:normal; }

/* Nested menus live above dialog surfaces as well as the document. */
[data-slot="menubar-content"], [data-slot="menubar-sub-content"] { z-index: var(--z-popover); }

/* Compact by default; --menu-width or inline width can deliberately match a large trigger. */
[data-slot="menubar-content"], [data-slot="menubar-sub-content"] { width:var(--menu-width,260px); min-width:min(200px,calc(100vw - 24px)); max-width:calc(100vw - 24px); color:var(--popover-foreground); }
[data-slot^="menubar-"][data-part="item"] { min-width:0; min-height:44px; padding-block:7px; gap:10px; white-space:normal; overflow-wrap:anywhere; text-align:start; }
[data-slot^="menubar-"][data-part="item"]:is(:hover,[data-highlighted],[data-state="checked"]) { background:var(--v-beige); color:var(--v-text); }
[data-slot^="menubar-"][data-part="item"][data-state="checked"] { background:var(--v-pink-soft); }
[data-slot^="menubar-"][data-part="item"]:active { background:var(--v-pink-soft); color:var(--v-text); }
[data-slot^="menubar-"][data-part="item"].-danger { color:var(--v-danger-ink); }
[data-slot^="menubar-"][data-part="item"][data-disabled] { background:transparent; color:var(--v-disabled-ink); }
[data-slot^="menubar-"] .v-menu__check { display:inline-grid; place-items:center; width:18px; min-width:18px; margin-inline-start:auto; color:inherit; }
[data-slot^="menubar-"] .v-menu__check .v-icon { width:16px; height:16px; }

[data-slot="menubar-trigger"] { display:inline-flex; align-items:center; gap:8px; min-height:36px; height:auto; color:var(--v-text); }
[data-slot="menubar-trigger"]:is(:hover,[data-highlighted],[data-state="open"],[aria-expanded="true"]) { background:var(--v-ink); color:var(--v-on-ink); --mfill:var(--v-ink); }
[data-slot="menubar-trigger"]:active { background:var(--v-pink); color:var(--v-on-accent); --mfill:var(--v-pink); }
[data-slot="menubar-trigger"][data-disabled] { background:transparent; color:var(--v-disabled-ink); --mfill:transparent; }

/* A native flyout may share a narrow viewport with its parent. Use Popper's
   measured free width so its labels wrap instead of leaving the screen. */
[data-slot="menubar-sub-content"] { min-width:min(200px,var(--radix-menubar-content-available-width,200px)); max-width:min(calc(100vw - 24px),var(--radix-menubar-content-available-width,260px)); }

/* The shared ScrollArea owns menu overflow and its custom thumb. */
:is([data-slot="menubar-content"],[data-slot="menubar-sub-content"]) .v-list-scroll { --list-scroll-max-height:min(320px, calc(var(--radix-popper-available-height, 60dvh) - 20px)); }

}
